MONTHS=['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
def display_date(value):
    d=date.fromisoformat(value)
    return f'{d.day} {MONTHS[d.month-1]} {d.year}'
e=lambda s:html.escape(str(s),quote=True)
def path(s):return PREFIX+s if s.startswith('/') else s
def link(url,label,cls='',external=False):
    extra=' target="_blank" rel="noopener noreferrer"' if external else ''
    return f'<a href="{e(path(url))}" class="{cls}"{extra}>{label}</a>'
def btn(url,label,light=False):return link(url,e(label)+' <span aria-hidden="true">↗</span>','button'+(' light' if light else ''),url.startswith('https:'))
WA='https://wa.me/'+S['phone'].replace('+','')+'?text='+quote('Merhaba, online beslenme danışmanlığı ve görüşme süreci hakkında bilgi almak istiyorum.')
def img(file,alt,cls='',eager=False):
    dims={'tugba-seker-agac.webp':(1200,1048),'adana-ofis.webp':(760,722),'tugba-klinik.webp':(952,868),'dengeli-beslenme.webp':(1400,933),'surdurulebilir-beslenme.webp':(1200,1600),'online-diyetisyen-kapak.webp':(1077,519),'tugba-kurumsal.webp':(1200,1600),'tugba-hizmetler.webp':(1200,1600),'tugba-blog-calisma.webp':(1200,800),'tugba-logo.webp':(221,292),'iskelet.webp':(1180,1200),'kas.webp':(803,628),'yag-dokusu.webp':(1200,482),'sindirim.webp':(450,531),'tugba-ofis-yesil.webp':(750,1000),'tugba-ofis-onluk.webp':(750,1000),'tugba-buket.webp':(750,1000),'tugba-sahil.webp':(750,1000),'tugba-doga.webp':(750,1000),'tugba-doga-genis.webp':(750,1000),'tugba-kirsal.webp':(750,1000),'tugba-doga-yakin.webp':(750,1000),'tugba-hero-orijinal.jpg':(1512,1320)}
    dims[LOGO]=(1977,762)
    dims[LOGO_LIGHT]=(1977,762)
    w,h=dims.get(file,(480,360) if file.startswith('video-') else (1280,720));load='fetchpriority="high"' if eager else 'loading="lazy"'
    return f'<img src="{e(path("/assets/images/"+file))}" alt="{e(alt)}" width="{w}" height="{h}" class="{cls}" {load} decoding="async">'
def brand(eager=False,light=False):
    logo=LOGO_LIGHT if light else LOGO
    return img(logo,'Diyetisyen Tuğba Şeker Ağaç elma ve kelebek logolu yatay marka işareti','brand-logo',eager=eager)
NAV=[('Ana Sayfa','/'),('Kurumsal','/kurumsal/'),('Online Diyetisyen','/online-diyetisyen/'),('Hizmetler','/hizmetler/'),('Blog','/blog/'),('SSS','/sikca-sorulan-sorular/'),('İletişim','/iletisim/')]
PAGES=[]
def layout(route,title,desc,body,kind='WebPage',extra=None,noindex=False,cover='tugba-ofis-yesil.webp'):
    canonical=BASE+route
    article=next((x for x in (extra or []) if x.get('@type')=='BlogPosting'),None)
    modified=article['dateModified'] if article else S.get('page_updates',{}).get(route,DATE)
    graph=[{'@type':'Person','@id':BASE+'/#diyetisyen','name':S['name'],'jobTitle':'Diyetisyen','url':BASE+'/kurumsal/','image':BASE+'/assets/images/tugba-ofis-onluk.webp','alumniOf':{'@type':'CollegeOrUniversity','name':'Erciyes Üniversitesi'},'sameAs':[S[x] for x in ['instagram','youtube','linkedin','reddit']]},
      {'@type':'ProfessionalService','@id':BASE+'/#kurum','name':S['name'],'url':BASE+'/','telephone':S['phone'],'image':BASE+'/assets/images/tugba-ofis-onluk.webp','logo':BASE+'/assets/images/'+LOGO,'founder':{'@id':BASE+'/#diyetisyen'},'areaServed':{'@type':'Country','name':'Türkiye'},'address':{'@type':'PostalAddress','streetAddress':S['address'].split(', Seyhan')[0],'addressLocality':'Seyhan','addressRegion':'Adana','postalCode':'01010','addressCountry':'TR'},'geo':{'@type':'GeoCoordinates','latitude':S['latitude'],'longitude':S['longitude']},'hasMap':S['map']},
      {'@type':'WebSite','@id':BASE+'/#website','url':BASE+'/','name':S['name'],'inLanguage':'tr-TR','publisher':{'@id':BASE+'/#kurum'}},
      {'@type':kind,'@id':canonical+'#webpage','url':canonical,'name':title,'description':desc,'inLanguage':'tr-TR','dateModified':modified,'isPartOf':{'@id':BASE+'/#website'},'about':{'@id':BASE+'/#diyetisyen'}}]
    if route!='/':graph.append({'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Ana Sayfa','item':BASE+'/'},{'@type':'ListItem','position':2,'name':title.split('|')[0].strip(),'item':canonical}]})
    if extra:graph.extend(extra)
    nav=''.join(f'<a href="{e(path(u))}"'+(' aria-current="page"' if route==u or (u=='/blog/' and route.startswith('/blog/')) or (u=='/hizmetler/' and route.startswith('/hizmetler/')) else '')+f'>{t}</a>' for t,u in NAV)
    header=f'''<a href="#main" class="skip">İçeriğe geç</a><div class="topbar"><div class="wrap"><span>TÜRKİYE GENELİNDE ONLINE · ADANA’DA YÜZ YÜZE DANIŞMANLIK</span><span>WhatsApp: Pazartesi–Cumartesi 08.00–20.00</span></div></div><header class="site-header"><div class="wrap nav-wrap">{link('/',brand(eager=True),'brand')}<button class="menu-toggle" type="button" aria-label="Menüyü aç" aria-expanded="false" aria-controls="site-nav"><span data-menu-label>Menü</span><span class="menu-icon" aria-hidden="true"><span></span><span></span></span></button><nav id="site-nav" class="nav" aria-label="Ana gezinme">{nav}{btn(WA,'Görüşme bilgisi')}</nav></div></header>'''
    footlinks=''.join(link(u,e(t)) for t,u in NAV[1:])
    social=''.join(link(S[k],v,external=True) for k,v in [('instagram','Instagram'),('youtube','YouTube'),('linkedin','LinkedIn'),('reddit','Reddit')])
    footer=f'''<section class="cta-band"><div class="wrap"><div><span class="eyebrow">BESLENME DANIŞMANLIĞI</span><h2>Size uygun bir başlangıcı konuşalım.</h2><p>Online görüşme veya Adana ofisi için iletişim ve randevu bilgileri.</p></div>{btn('/iletisim/','İletişime geçin')}</div></section><footer class="site-footer"><div class="wrap"><div class="footer-grid"><div>{link('/',brand(light=True),'brand')}<p>Türkiye genelinde online diyetisyen danışmanlığı ve Adana’da yüz yüze beslenme görüşmeleri.</p><p>İçerikler genel bilgilendirme amaçlıdır. Kişisel tanı, tedavi veya beslenme planı yerine geçmez.</p></div><div><h3>KEŞFEDİN</h3><div class="footer-links">{footlinks}</div></div><div><h3>BİLGİ &amp; KAYNAKLAR</h3><div class="footer-links">{link('/vucudunu-tani/','Vücudunu Tanı')}{link('/bki-hesaplama/','BKİ Hesaplama')}{link('/videolar/','Videolar')}{link('/kaynaklar/','Kaynaklar ve içerik ilkeleri')}{link('/gizlilik/','Gizlilik ve veri kullanımı')}</div></div><div><h3>ADANA OFİSİ &amp; ONLINE</h3><p>{e(S['address'])}</p><div class="footer-links">{link('tel:'+S['phone'],e(S['phone_display']))}{link(S['map'],'Konumu aç ↗',external=True)}{link(WA,'WhatsApp ↗',external=True)}</div><p style="margin-top:18px">WhatsApp: {e(S['whatsapp_hours'])}<br>Pazar kapalı · Ofis görüşmeleri randevuyla.</p><div class="social-list">{social}</div></div></div><div class="footer-bottom"><p>© 2026 {e(S['name'])}.<br>İçerik güncelleme: {display_date(modified)} · Editör iletişimi: {link('tel:'+S['phone'],e(S['phone_display']))}</p><p>{link('/adana-diyetisyen/','Adana diyetisyen')} · {link('/online-diyetisyen/','Online diyetisyen')} · {link('/feed.xml','RSS')}</p></div></div></footer>{link(WA,'WhatsApp · Görüşme bilgisi ↗','floating-contact',True)}<div class="mobile-contact" aria-label="Hızlı iletişim">{link('tel:'+S['phone'],'Telefonla ara')}{link(S['instagram'],'Instagram',external=True)}{link(WA,'WhatsApp ↗',external=True)}</div>'''
    doc=f'''<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}"><link rel="canonical" href="{e(canonical)}"><meta name="theme-color" content="#164e33"><link rel="icon" type="image/png" sizes="768x768" href="{path('/assets/images/'+FAVICON)}"><link rel="alternate" type="application/rss+xml" title="Beslenme Blogu" href="{path('/feed.xml')}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:locale" content="tr_TR"><meta property="og:site_name" content="{e(S['name'])}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{e(canonical)}"><meta property="og:image" content="{BASE}/assets/images/{cover}"><meta property="og:image:alt" content="{e(S['name'])} beslenme rehberi"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="{path('/assets/style.css')}?v=prices-v1"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False).replace('<','\\u003c')}</script><script defer src="{path('/assets/calculator.js')}"></script><script defer src="{path('/assets/app.js')}?v=hero-original-v6"></script><noscript><style>.site-header .nav{{display:flex;position:static;flex:1 0 100%;flex-wrap:wrap;flex-direction:row;max-height:none;overflow:visible;box-shadow:none;margin-bottom:12px}}.site-header .menu-toggle{{display:none}}.site-header .nav-wrap{{flex-wrap:wrap}}</style></noscript></head><body>{header}<main id="main">{body}</main>{footer}</body></html>'''
    if PREFIX:
        # Content HTML also uses absolute internal URLs.
        doc=re.sub(r'(href|src)="/(?!/|'+re.escape(PREFIX.lstrip('/'))+r'(?:/|"))',lambda m:m[1]+'="'+PREFIX+'/',doc)
    filename=OUT/('index.html' if route=='/' else '404.html' if route=='/404.html' else route.strip('/')+'/index.html')
    filename.parent.mkdir(parents=True,exist_ok=True);filename.write_text(doc)
    if not noindex:PAGES.append((route,title,modified))

def eyebrow(s):return f'<span class="eyebrow">{e(s)}</span>'
def heading(kicker,title,desc='',more=None):return '<div class="section-heading"><div>'+eyebrow(kicker)+f'<h2>{title}</h2>'+('<p class="muted">'+desc+'</p>' if desc else '')+'</div>'+(link(more[0],more[1]+' <span aria-hidden="true">↗</span>','text-link') if more else '')+'</div>'
def hero(title,intro,kicker,photo=None,photo_cls='',photo_alt=None):
    crumb=f'<div class="breadcrumb">{link("/","Ana Sayfa")} / {e(kicker)}</div>'
    copy=eyebrow(kicker)+f'<h1>{title}</h1><p class="lead">{intro}</p>'
    return '<section class="page-hero'+(' has-photo' if photo else '')+'"><div class="wrap">'+crumb+('<div class="split"><div>'+copy+'</div>'+img(photo,photo_alt or S['name'],photo_cls,eager=True)+'</div>' if photo else copy)+'</div></section>'
