def cards(items=None):
    data=SERVICE_CATALOG if items is None else [{'icon':'•','title':s['title'],'short':s['short'],'bullets':[],'url':'/hizmetler/'+s['slug']+'/'} for s in items]
    out=[]
    for s in data:
        title=link(s['url'],e(s['title'])) if s.get('url') else e(s['title'])
        bullets=''.join('<li>'+e(x)+'</li>' for x in s.get('bullets',[]))
        out.append(f'<article class="service-card-v2"><span class="service-icon-v2" aria-hidden="true">{e(s["icon"])}</span><h3>{title}</h3><p>{e(s["short"])}</p>'+('<ul>'+bullets+'</ul>' if bullets else '')+link(s['url'],'Detaylı İncele <span aria-hidden="true">→</span>','service-detail-link')+'</article>')
    return '<div class="services-catalog-grid">'+''.join(out)+'</div>'
def services_showcase(page=False):
    tag='h1' if page else 'h2'
    crumb=('<div class="breadcrumb">'+link('/','Ana Sayfa')+' / Hizmetler</div>') if page else ''
    title=f'<{tag}>Online (Uzaktan) Diyetisyen <span class="accent">Hangi Hizmetleri Verir?</span></{tag}>'
    return f'''<section class="section services-showcase"><div class="wrap">{crumb}<div class="services-showcase-head"><div class="services-showcase-copy">{eyebrow('HİZMETLERİMİZ')}{title}<p class="lead">Online diyetisyen desteği; kilo yönetiminden farklı yaşam dönemlerine ve hekim tanısı bulunan durumlarda beslenme takibine kadar geniş bir alanda, kişisel değerlendirmeyle planlanabilir.</p><div class="services-values"><span>🌿 Kişiye özel yaklaşım</span><span>♡ Sürdürülebilir planlama</span><span>◎ Her yaşam dönemine uygun</span></div></div><figure class="services-showcase-photo">{img('tugba-ofis-yesil.webp','Diyetisyen Tuğba Şeker Ağaç yeşil elbisesiyle Adana ofisinde','',eager=page)}<figcaption><small>DİYETİSYEN</small><strong>Tuğba Şeker Ağaç</strong><span>Online danışmanlık · Adana</span></figcaption></figure></div>{cards()}</div></section>'''
def steps():
    values=[('Tanışalım','Günlük düzeninizi, beklentilerinizi ve mevcut sağlık bilgilerinizi konuşalım.'),('Birlikte planlayalım','Öğünlerinizi yaşam ritminize, tercihlerinize ve gereksinimlerinize göre ele alalım.'),('Takip edelim','Uygulama deneyiminizi haftalık görüşmelerde değerlendirelim.'),('Hayatınıza uyarlayalım','İhtiyaçlarınıza göre alternatifler ve sürdürülebilir alışkanlıklar üzerinde çalışalım.')]
    return '<div class="steps">'+''.join(f'<div class="step"><span aria-hidden="true">{i:02}</span><h3>{a}</h3><p>{b}</p></div>' for i,(a,b) in enumerate(values,1))+'</div>'
FAQ=[('Online diyetisyen görüşmesi hangi şehirlerde yapılabilir?','Türkiye’nin farklı şehirlerinden online görüşmeye katılabilirsiniz. İhtiyaçlarınız ve online görüşmeye uygunluk ilk iletişimde değerlendirilir. Adana’da yüz yüze görüşme seçeneği de vardır.'),('İlk görüşmede ne konuşulur?','Sağlık öykünüz, mevcut tanılarınız, günlük öğünleriniz, çalışma düzeniniz, hareket alışkanlıklarınız ve beklentileriniz değerlendirilir. Mevcut tetkiklerinizi ve ilaç bilgilerinizi hazır bulundurabilirsiniz.'),('Beslenme listesi herkese aynı mı hazırlanır?','Plan; sağlık durumunuz, gereksinimleriniz ve günlük yaşamınız dikkate alınarak kişiye göre düzenlenir. Öğün alternatifleri takipte yeniden değerlendirilebilir.'),('WhatsApp üzerinden hangi saatlerde iletişim kurabilirim?','Pazartesi–cumartesi günleri 08.00–20.00 arasında iletişim kurabilirsiniz. Pazar günleri kapalıdır. Görüşmeler önceden belirlenen randevu saatinde yapılır.'),('BKİ aracı yağ oranımı gösterir mi?','Hayır. Araç boy ve ağırlık üzerinden beden kütle indeksini hesaplar. Yağ veya kas oranınızı ölçmez; tanı koymaz. 20 yaş altı ve gebelik için kullanılmaz.'),('Ne kadar sürede sonuç alırım?','Süreç kişinin sağlık durumuna, gereksinimlerine ve günlük koşullarına göre değişir. Belirli sürede kesin kilo değişimi veya aynı sonucu elde etme garantisi verilmez.')]
def faqs(items=FAQ):return '<div class="faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in items)+'</div>'+('<p class="faq-more">'+link('/sikca-sorulan-sorular/','Tüm sıkça sorulan sorular','text-link')+'</p>' if items is FAQ else '')
def bmi():return '''<div class="calc"><h3>Beden kütle indeksini hesapla</h3><p>Boy ve kilo bilgilerinle genel bir tarama göstergesi olan BKİ’ni öğren.</p><form data-bmi-form novalidate><fieldset disabled style="border:0;padding:0;margin:0"><div class="input-grid"><label>Boy (cm)<input name="height" inputmode="decimal" autocomplete="off" placeholder="Örn. 165" aria-label="Boy, santimetre" required></label><label>Kilo (kg)<input name="weight" inputmode="decimal" autocomplete="off" placeholder="Örn. 65" aria-label="Kilo, kilogram" required></label><label>Yaş<input name="age" inputmode="numeric" autocomplete="off" placeholder="20 ve üzeri" required></label></div><label class="checkbox"><input type="checkbox" name="eligible">20 yaş veya üzerindeyim ve gebelik durumum yok. Bu aracın tanı veya yağ ölçümü olmadığını biliyorum.</label><button class="button" type="submit">BKİ’mi hesapla <span aria-hidden="true">↗</span></button></fieldset><p class="calc-error" data-error role="alert"></p><div class="calc-result" data-result aria-live="polite" hidden><strong></strong><p data-category></p><p>Bu sonuç tek başına sağlık durumunuzu göstermez. Kas kütlesi ve sağlık öykünüz gibi etkenlerle birlikte yorumlanmalıdır.</p></div></form><p class="calc-note">Bilgileriniz kaydedilmez veya sunucuya gönderilmez. Hesaplama yalnızca bu cihazda yapılır. <a href="https://www.cdc.gov/bmi/adult-calculator/index.html" target="_blank" rel="noopener noreferrer"><u>Kaynak: CDC</u></a></p><noscript><p>Hesaplayıcı için JavaScript gerekir. Formül: ağırlık (kg) ÷ boy (m)². Yetişkin sınıflaması yalnızca uygun kişilerde yorumlanır.</p></noscript></div>'''

ANATOMY=[
 ('iskelet','Kemikler','Vücudunun destek sistemi','Kemikler vücuda destek sağlar, organları korur ve kaslarla birlikte hareketi mümkün kılar. Kalsiyum ile D vitamini kemik sağlığının beslenmeyle ilgili parçalarıdır.','Beslenme bağlantısı: besin çeşitliliği ve bireysel gereksinimler.','iskelet.webp','İskeletin önden ve arkadan görünümü; merkezi iskelet ve uzuv kemikleri','https://commons.wikimedia.org/wiki/File:701_Axial_Skeleton-01.jpg','3.0','https://ods.od.nih.gov/factsheets/Calcium-Consumer/'),
 ('kas','Kaslar','Hareketin arkasındaki doku','İskelet kasları lif demetlerinden oluşur. Kasılma sırasında enerji kullanılır ve kuvvet tendonlar aracılığıyla kemiklere aktarılır.','Beslenme bağlantısı: öğünlerin bütünü, enerji gereksinimi ve aktivite düzeyi.','kas.webp','Kas lifinin iç yapısını, miyofibrilleri ve sarkomeri gösteren çizim','https://commons.wikimedia.org/wiki/File:1002_Organization_of_Muscle_Fiber.jpg','4.0','https://openstax.org/books/anatomy-and-physiology-2e/pages/10-2-skeletal-muscle'),
 ('yag','Yağ dokusu','Bir sayıdan fazlası','Yağ dokusu enerji depolayan ve vücudun yalıtımında rol alan bir dokudur. Tartıdaki toplam ağırlık, bu dokunun miktarını tek başına göstermez.','Beslenme bağlantısı: yağ dokusunu anlamak, kilo takibini daha doğru yorumlamak.','yag-dokusu.webp','Yağ hücreleri, çekirdekleri ve yağ damlacıklarını gösteren çizim ve mikroskop görüntüsü','https://commons.wikimedia.org/wiki/File:409_Adipose_Tissue.jpg','3.0','https://openstax.org/books/anatomy-and-physiology-2e/pages/4-3-connective-tissue-supports-and-protects'),
 ('sindirim','Sindirim','Yediğin besinin yolculuğu','Sindirim ağızda başlar. Mide ve bağırsaklar besinlerin parçalanması ve emiliminde görev alır. Besin öğelerinin büyük bölümü ince bağırsaktan emilir.','Beslenme bağlantısı: öğün düzeni, bireysel tolerans ve sindirim yakınmalarının değerlendirilmesi.','sindirim.webp','Ağız, yemek borusu, mide, karaciğer, pankreas ve bağırsakların anatomik yerleşimi','https://www.niddk.nih.gov/health-information/digestive-diseases/digestive-system-how-it-works',None,'https://www.niddk.nih.gov/health-information/digestive-diseases/digestive-system-how-it-works')]
def attribution(file):
    if file=='surdurulebilir-beslenme.webp':return 'Görsel: Diyetisyen Tuğba Şeker Ağaç tarafından sağlanan özgün Canva tasarımı.'
    if file=='online-diyetisyen-kapak.webp':return 'Görsel: Diyetisyen Tuğba Şeker Ağaç tarafından sağlanan özgün Canva tasarımı.'
    a=next((x for x in ANATOMY if x[5]==file),None)
    if not a:return 'Yapay zekâyla hazırlanmış temsili öğün görseli; kişisel diyet reçetesi değildir.' if file=='dengeli-beslenme.webp' else ''
    license=f' · <a href="https://creativecommons.org/licenses/by/{a[8]}/" target="_blank" rel="noopener noreferrer">CC BY {a[8]}</a>' if a[8] else ''
    return f'<a href="{a[7]}" target="_blank" rel="noopener noreferrer">{"OpenStax" if a[8] else "NIDDK / NIH"}</a>{license} · WebP dönüşümü ve boyutlandırma. Özgün etiketler İngilizcedir.'
def anatomy():
    buttons=''.join(f'<button class="chip" type="button" data-topic="{a[0]}" aria-pressed="false" aria-controls="anat-{a[0]}">{a[1]}</button>' for a in ANATOMY)
    panels=''.join(f'<div class="anatomy-panel" data-panel="{a[0]}" id="anat-{a[0]}"><h3>{a[2]}</h3><p>{a[3]}</p><p class="micro">{a[4]}</p><p class="micro">{link(a[9],"Bilimsel kaynağı inceleyin ↗",external=True)}</p></div>' for a in ANATOMY)
    figs=''.join(f'<figure class="anatomy-art" data-figure="{a[0]}">{img(a[5],a[6])}<figcaption>{attribution(a[5])}</figcaption></figure>' for a in ANATOMY)
    return f'<div class="anatomy" data-anatomy><div>{eyebrow("BESLENMENİN BİLİMİ")}<h2>Vücudunu tanı.<br><span class="accent">İhtiyacını anla.</span></h2><div class="anatomy-controls" role="group" aria-label="Anatomi konusu" data-js-only hidden>{buttons}</div>{panels}{link("/vucudunu-tani/","Anatomi rehberini keşfedin ↗","text-link")}</div><div>{figs}</div></div>'
def post_cards(posts=POSTS,searchable=False):
    out=[]
    for p in posts:
        u='/blog/'+p['slug']+'/'
        attrs=f' data-post data-category="{e(p["category"])}" data-search="{e(p["title"]+" "+p["description"])}"' if searchable else ''
        cover_class='post-cover'+(' science' if p.get('science') else '')+(' portrait' if p.get('portrait') else '')
        cover=link(u,img(p['image'],p['image_alt']),cover_class)
        out.append(f'<article class="post-card"{attrs}>{cover}<div class="micro">{e(p["category"])} · {reading_time(p)} dk okuma</div><h3>{link(u,e(p["title"]))}</h3><p>{e(p["description"])}</p>{link(u,"Yazıyı okuyun ↗","text-link")}</article>')
    return '<div class="grid-3">'+''.join(out)+'</div>'
def reading_time(p):return max(2,round(len(re.sub('<[^>]+>',' ',p['intro']+' '.join(s['body'] for s in p['sections'])).split())/180))
VIDEOS=[('yJBjeg2Csrs','Ramazan ayında beslenme','Ramazan dönemindeki beslenme düzenine ilişkin kanal paylaşımı.'),('6IfEDX0r8zQ','Şekersiz kek tarifi','Evde hazırlanabilecek tariflere kanaldan bir örnek.'),('U-Ae6qZYAZs','Çorba tarifi','Günlük mutfağa uygun bir tarif videosu.')]
def video_cards():
    return '<div class="grid-3">'+''.join(f'<article class="video-card"><div class="video-slot"><button class="video-load" type="button" data-video="{v}" data-title="{e(t)}" aria-label="{e(t)} videosunu oynat">{img("video-"+v+".webp",t+" video kapağı")}<span class="play" aria-hidden="true">▶</span></button></div><h3>{e(t)}</h3><p>{e(d)}</p>{link("https://www.youtube.com/watch?v="+v,"YouTube’da aç ↗","text-link",True)}</article>' for v,t,d in VIDEOS)+'</div>'
def social_block():return f'''<div class="social-feature"><div>{eyebrow('INSTAGRAM’DA BULUŞALIM')}<h2>Beslenmeyi günlük hayatın içinde konuşuyoruz.</h2><p>Tarifler, beslenme notları ve gündelik sorulara ilişkin paylaşımlar için resmî Instagram hesabı.</p>{link(S['instagram'],'@dyt.tugbasekeragac ↗','text-link',True)}<div class="social-list">{link(S['youtube'],'YouTube ↗',external=True)}{link(S['linkedin'],'LinkedIn ↗',external=True)}{link(S['reddit'],'Reddit ↗',external=True)}</div></div>{img('tugba-buket.webp','Diyetisyen Tuğba Şeker Ağaç, çiçeklerle gülümserken')}</div>'''
REVIEWS=[
    ('Sibel B.','“Sıkmadan, yormadan destek olan bir yol arkadaşı.”'),
    ('Neslihan K.','“Hayatı düzene sokan, sürdürülebilir bir beslenme tarzı.”'),
    ('A. A.','“Keyifli ve öğretici bir süreç; sağlıklı yaşam alışkanlığı kazandırıyor.”'),
]
def reviews_block():
    rating=str(S.get('review_rating',5.0)).replace('.',',')
    count=e(S.get('review_count',''))
    reviews_url=S.get('reviews_url',S['map'])
    cards=''.join(f'<article class="review-card"><div class="review-stars" aria-label="5 yıldız">★★★★★</div><blockquote>{e(quote)}</blockquote><div class="review-meta"><strong>{e(name)}</strong><br><span>Google İşletme Profili · kısa alıntı</span></div></article>' for name,quote in REVIEWS)
    return f'''<section class="section review-section"><div class="wrap"><div class="section-heading"><div>{eyebrow('DANIŞAN DENEYİMLERİ')}<h2>İyi hissettiren bir süreç.</h2><p class="muted">Google İşletme Profilindeki gerçek değerlendirmelerden kısa bir seçki.</p></div>{btn(reviews_url,'Google’da tüm yorumları gör',True)}</div><div class="review-summary"><span class="review-score">{rating}</span><span class="review-stars" aria-hidden="true">★★★★★</span><span class="review-count">Google’da {count} yorum</span></div><div class="review-grid">{cards}</div><p class="review-note">Puan ve yorum sayısı Google profilinde zamanla değişebilir. Alıntılar okunaklı olması için kısaltılmıştır; tüm yorumlar Google profilinde yer alır.</p></div></section>'''
def sidebar():return f'<aside class="sidebar"><h3>Tanışalım.</h3><p>Online danışmanlık veya Adana ofisi için görüşme sürecini öğrenebilirsiniz.</p>{btn(WA,"WhatsApp ile iletişim")}{btn("tel:"+S["phone"],"Telefonla arayın",True)}<p>WhatsApp: {e(S["whatsapp_hours"])}<br>Pazar kapalı.</p><nav aria-label="İlgili sayfalar">{link("/online-diyetisyen/","Online danışmanlık süreci ↗")}{link("/vucudunu-tani/","Vücudunu Tanı ↗")}{link("/blog/","Diğer beslenme yazıları ↗")}</nav></aside>'
def article_body(content):return '<section class="section"><div class="wrap article-layout"><div class="prose">'+content+'</div>'+sidebar()+'</div></section>'

